<?php
if(session_status()!==PHP_SESSION_ACTIVE)session_start();
if(empty($_SESSION['id_user'])){header('Location: login.php');exit;}
require_once __DIR__.'/conexao.php';require_once __DIR__.'/reading_goal_support.php';
$conn=$conn??(new Database)->conectar();$id_user=(int)$_SESSION['id_user'];
$id=filter_var($_GET['atualizar']??null,FILTER_VALIDATE_INT);
$stmt=$conn->prepare('SELECT * FROM meta_leitura WHERE id=? AND id_user=?');$stmt->execute([$id?:0,$id_user]);$meta=$stmt->fetch();
if(!$meta){http_response_code(404);exit('Meta não encontrada.');}
$_SESSION['goal_csrf']??=bin2hex(random_bytes(32));$erro='';
if($_SERVER['REQUEST_METHOD']==='POST'){
    $nome=trim(is_string($_POST['nome_meta']??null)?$_POST['nome_meta']:'');$periodo=is_string($_POST['periodo']??null)?$_POST['periodo']:'';
    $quantidade=($meta['tipo_meta']??'livros')==='listas'?(int)$meta['num_livros']:filter_var($_POST['quantidade']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1,'max_range'=>10000]]);
    $prazo=prazoMeta($periodo,is_string($_POST['data_limite']??null)?$_POST['data_limite']:null);
    if(!is_string($_POST['csrf']??null)||!hash_equals($_SESSION['goal_csrf'],$_POST['csrf'])){http_response_code(403);$erro='Sua sessão expirou. Recarregue a página.';}
    elseif($nome===''||mb_strlen($nome)>100||!$quantidade||!$prazo){http_response_code(422);$erro='Revise o nome, a quantidade e o prazo da meta.';}
    else{try{$stmt=$conn->prepare("UPDATE meta_leitura SET nome_meta=?,periodo=?,expiracao=?,status=CASE WHEN num_livros<>? THEN 'andamento' ELSE status END,num_livros=? WHERE id=? AND id_user=?");$stmt->execute([$nome,$periodo,$prazo->format('Y-m-d'),$quantidade,$quantidade,$id,$id_user]);$_SESSION['meta_feedback']='Meta atualizada. Seu histórico de leituras foi preservado.';header('Location: perfil.php?aba=visao-geral&metas=1');exit;}catch(PDOException $e){error_log('Atualizar meta: '.$e->getMessage());$erro='Não foi possível atualizar sua meta. Tente novamente.';}}
}
$esc=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');
?>
<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="icon" href="../img/icons/ico-nook/ico-nook.ico" type="image/x-icon"><link rel="stylesheet" href="../front-end/css/main.css"><link rel="stylesheet" href="../front-end/css/pages/publishing.css"><link href="https://fonts.googleapis.com/css2?family=Lora:wght@400;500;600&amp;family=Manrope:wght@400;500;600&amp;display=swap" rel="stylesheet"><title>Atualizar meta | Nook</title></head><body><?php require __DIR__.'/header.php';?><main class="writing-page"><a href="perfil.php?aba=visao-geral&amp;metas=1" class="writing-back">← Voltar às metas</a><h1>Atualizar meta</h1><p>Seu histórico de leituras será preservado.</p><?php if($erro):?><p role="alert"><?=$esc($erro)?></p><?php endif;?><form method="post" class="writing-metadata writing-fields"><input type="hidden" name="csrf" value="<?=$esc($_SESSION['goal_csrf'])?>"><label class="writing-field-wide">Nome da meta<input name="nome_meta" maxlength="100" value="<?=$esc($_POST['nome_meta']??$meta['nome_meta'])?>" required></label><label>Quantidade de <?=($meta['tipo_meta']??'livros')==='listas'?'listas':'livros'?><input type="number" name="quantidade" min="1" max="10000" value="<?=(int)($meta['tipo_meta']==='listas'?$meta['num_livros']:($_POST['quantidade']??$meta['num_livros']))?>" <?=($meta['tipo_meta']??'livros')==='listas'?'readonly':''?> required></label><label>Período<select name="periodo"><?php foreach(['semanal'=>'Semanal','mensal'=>'Mensal','semestral'=>'Semestral','anual'=>'Anual','personalizado'=>'Personalizado'] as $valor=>$rotulo):?><option value="<?=$valor?>" <?=($_POST['periodo']??$meta['periodo'])===$valor?'selected':''?>><?=$rotulo?></option><?php endforeach;?></select></label><label>Data para período personalizado<input type="date" name="data_limite" value="<?=$esc($_POST['data_limite']??substr($meta['expiracao'],0,10))?>"><small>Utilizada somente quando o período for personalizado.</small></label><div class="writing-field-wide"><button class="writing-primary">Salvar alterações</button></div></form></main></body></html>
